import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.BrO6lPIi.js";const u=JSON.parse('{"title":"HTTP/WebSocket 服务器","description":"健康检查接口 `/api/status` 返回版本、运行状态、平台信息、搜索工具可用性、RAG 可用性。","frontmatter":{"title":"HTTP/WebSocket 服务器","description":"健康检查接口 `/api/status` 返回版本、运行状态、平台信息、搜索工具可用性、RAG 可用性。"},"headers":[],"relativePath":"系统架构设计/Agent-服务架构/HTTP_WebSocket-服务器/index.md","filePath":"系统架构设计/Agent-服务架构/HTTP_WebSocket-服务器/index.md","lastUpdated":null}'),i={name:"系统架构设计/Agent-服务架构/HTTP_WebSocket-服务器/index.md"};function l(n,e,s,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="http-websocket-服务器" tabindex="-1">HTTP/WebSocket 服务器 <a class="header-anchor" href="#http-websocket-服务器" aria-label="Permalink to &quot;HTTP/WebSocket 服务器&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js" target="_blank" rel="noreferrer">agent/src/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js" target="_blank" rel="noreferrer">agent/src/auth.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js" target="_blank" rel="noreferrer">agent/src/memory/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#简介">简介</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与并发特性">性能与并发特性</a></li><li><a href="#api-端点规范">API 端点规范</a></li><li><a href="#错误码与响应约定">错误码与响应约定</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>本文面向 Agent 端的本地 HTTP/WebSocket 服务，基于 Node.js 原生 <code>http</code> 模块和 <code>ws</code> 库实现。该服务是 Chrome 扩展与本机能力之间的桥梁：扩展通过本地端口调用 Agent 的文件读写、命令执行、长期记忆、RAG、MCP 工具、技能系统等功能；Agent 负责安全校验、路径沙箱、命令分级、进程管理、流式输出、配置持久化以及优雅关闭。</p><p>关键约束：</p><ul><li>双进程架构：Chrome 扩展端（Manifest V3）与独立本地 Agent 进程（Node.js）。</li><li>修改 Agent 源码后必须重启进程，新接口才生效。</li><li>默认监听 <code>127.0.0.1:18910</code>，仅本机可访问；若绑定到 <code>0.0.0.0</code>，远程请求仍需认证。</li><li>所有业务接口统一返回 <code>{ success, ... }</code> JSON 结构，错误信息使用 i18n 文案。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L10" target="_blank" rel="noreferrer">agent/package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li></ul><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>Agent 的 HTTP/WebSocket 入口位于 <code>agent/src/server.js</code>，它同时承担以下职责：</p><ul><li>启动 Node.js HTTP 服务器并注册路由。</li><li>解析请求体、处理 CORS、国际化语言切换。</li><li>执行认证、配对、工作目录切换、文件操作、命令执行、Skill/MCP/RAG/Memory 路由分发。</li><li>创建 WebSocket 升级处理器，用于命令执行结果流式推送。</li><li>管理进程生命周期、优雅关闭、信号处理和全局异常捕获。</li></ul><pre class="mermaid">graph TB
Client[&quot;客户端&lt;br/&gt;Chrome 扩展 / CLI / 脚本&quot;] --&gt; HTTP[&quot;HTTP 服务器&lt;br/&gt;server.js&quot;]
HTTP --&gt; Router[&quot;请求路由与中间件&lt;br/&gt;server.js&quot;]
Router --&gt; Auth[&quot;认证与配对&lt;br/&gt;auth.js&quot;]
Router --&gt; Security[&quot;路径与命令安全&lt;br/&gt;security.js&quot;]
Router --&gt; Config[&quot;配置加载与保存&lt;br/&gt;config.js&quot;]
Router --&gt; FS[&quot;文件系统接口&lt;br/&gt;server.js&quot;]
Router --&gt; Exec[&quot;命令执行器&lt;br/&gt;executor.js&quot;]
Router --&gt; Memory[&quot;长期记忆路由&lt;br/&gt;memory/routes.js&quot;]
Router --&gt; RAG[&quot;RAG 路由按需加载&quot;]
Router --&gt; MCP[&quot;MCP 工具路由&quot;]
Router --&gt; Skill[&quot;技能路由&quot;]
HTTP --&gt; WS[&quot;WebSocket 升级&lt;br/&gt;server.js&quot;]
WS --&gt; ExecWS[&quot;命令执行 WebSocket 广播&lt;br/&gt;executor.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2086-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2086-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L57" target="_blank" rel="noreferrer">agent/src/server.js#L1-L57</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>关键行为</th></tr></thead><tbody><tr><td>HTTP 服务器</td><td>监听端口、接收请求、触发路由</td><td>使用 <code>http.createServer</code>，在 <code>handleRequest</code> 中完成 i18n、CORS、认证、路由分发</td></tr><tr><td>认证模块</td><td>配对码生成、Token 验证、活跃连接窗口</td><td>支持连续失败锁定、一次性配对码、最近认证时间戳</td></tr><tr><td>安全模块</td><td>路径白名单、硬阻止目录、命令黑白名单</td><td>跨平台路径规整、符号链接 realpath 校验、链式命令拆分、解释器内联载荷检测</td></tr><tr><td>配置模块</td><td>配置文件加载、写入锁、内存缓存</td><td>默认端口 18910、host 127.0.0.1、workdir、allowedPaths、pairCodeTTL、commandTimeout</td></tr><tr><td>命令执行器</td><td>子进程执行、流式 stdout/stderr、超时策略</td><td>支持同步等待、异步 WebSocket 广播、受管模式超时延长、进程树终止</td></tr><tr><td>记忆路由</td><td><code>/api/memory/*</code> 业务分发</td><td>store/recall/manage/inject/reindex，embedding 配置与探活</td></tr><tr><td>WebSocket 服务器</td><td>命令执行结果实时推送</td><td>按 execId 关联进程、心跳 ping/pong、半开连接检测、断开清理</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L127" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L19-L27" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L19-L27</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示一次典型请求的生命周期：从 HTTP 请求进入、i18n 初始化、CORS 预检、认证、路由匹配、安全检查、业务处理，到最终 JSON 响应或 WebSocket 流式输出。</p><pre class="mermaid">sequenceDiagram
participant C as &quot;客户端&quot;
participant H as &quot;HTTP 服务器&quot;
participant R as &quot;请求处理器&quot;
participant A as &quot;认证模块&quot;
participant S as &quot;安全模块&quot;
participant E as &quot;命令执行器&quot;
participant W as &quot;WebSocket 服务器&quot;
C-&gt;&gt;H : &quot;POST /api/exec&quot;
H-&gt;&gt;R : &quot;handleRequest(req,res)&quot;
R-&gt;&gt;R : &quot;解析 Accept-Language&lt;br/&gt;设置各模块语言&quot;
R-&gt;&gt;R : &quot;CORS OPTIONS 预检&quot;
R-&gt;&gt;A : &quot;验证 Authorization Bearer Token&quot;
A--&gt;&gt;R : &quot;extId 或 401/403&quot;
R-&gt;&gt;S : &quot;检查 cwd 与 command&quot;
S--&gt;&gt;R : &quot;allow / confirm / deny&quot;
alt &quot;deny&quot;
R--&gt;&gt;C : &quot;403 {success : false,error}&quot;
else &quot;confirm&quot;
R--&gt;&gt;C : &quot;200 {level : &#39;confirm&#39;,reason}&quot;
else &quot;allow&quot;
R-&gt;&gt;E : &quot;executeCommand(command,cwd,timeoutMs)&quot;
E--&gt;&gt;R : &quot;execId + wsUrl&quot;
R--&gt;&gt;C : &quot;200 {success : true,execId,wsUrl}&quot;
C-&gt;&gt;W : &quot;WebSocket /ws/exec/{execId}?token=...&quot;
W-&gt;&gt;E : &quot;addWsClient(execId,ws)&quot;
E--&gt;&gt;W : &quot;stdout/stderr/exit/error 广播&quot;
W--&gt;&gt;C : &quot;实时消息流&quot;
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L548" target="_blank" rel="noreferrer">agent/src/server.js#L427-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L548" target="_blank" rel="noreferrer">agent/src/server.js#L427-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="http-路由与中间件管道" tabindex="-1">HTTP 路由与中间件管道 <a class="header-anchor" href="#http-路由与中间件管道" aria-label="Permalink to &quot;HTTP 路由与中间件管道&quot;">​</a></h3><p>HTTP 服务器在 <code>startServer</code> 中创建，并通过 <code>handleRequest</code> 实现统一的请求处理流程：</p><ol><li>初始化 i18n，将当前请求语言同步到 config、auth、security、executor、memory、rag、skill、mcp 等模块。</li><li>处理 CORS 预检请求，仅放行 <code>chrome-extension://</code> 来源。</li><li>解析 URL，每次请求重新加载配置，确保 workdir 切换后立即生效。</li><li>先处理无需认证的接口：<code>/api/pair</code>、<code>/api/status</code>、<code>/api/shutdown</code>。</li><li>再处理需认证的接口：<code>/api/heartbeat</code>、<code>/api/agent/restart</code>、<code>/api/agent/update</code>、文件接口、命令接口、Skill、MCP、RAG、Memory。</li><li>未匹配的路径返回 404。</li></ol><pre class="mermaid">flowchart TD
Start([&quot;HTTP 请求进入&quot;]) --&gt; I18n[&quot;初始化 i18n&lt;br/&gt;同步各模块语言&quot;]
I18n --&gt; Options{&quot;OPTIONS 预检?&quot;}
Options --&gt; |是| Cors[&quot;设置 ACAO&lt;br/&gt;仅 chrome-extension&quot;]
Options --&gt; |否| ParseURL[&quot;解析 URL&lt;br/&gt;重新加载配置&quot;]
Cors --&gt; RouteMatch[&quot;路由匹配&quot;]
ParseURL --&gt; RouteMatch
RouteMatch --&gt; PairCheck{&quot;/api/pair ?&quot;}
PairCheck --&gt; |是| Pair[&quot;handlePairRequest&quot;]
PairCheck --&gt; |否| StatusCheck{&quot;/api/status ?&quot;}
StatusCheck --&gt; |是| Status[&quot;返回平台信息&quot;]
StatusCheck --&gt; |否| ShutdownCheck{&quot;/api/shutdown ?&quot;}
ShutdownCheck --&gt; |是| Shutdown[&quot;本机免认证&lt;br/&gt;远程需 Bearer&quot;]
ShutdownCheck --&gt; |否| AuthCheck{&quot;Authorization Bearer ?&quot;}
AuthCheck --&gt; |否| NoToken[&quot;401 noToken&quot;]
AuthCheck --&gt; |是| Verify[&quot;verifyToken&quot;]
Verify --&gt; Valid{&quot;extId 有效?&quot;}
Valid --&gt; |否| InvalidToken[&quot;403 invalidToken&quot;]
Valid --&gt; |是| Business[&quot;业务路由分发&quot;]
Business --&gt; End([&quot;JSON 响应&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L548" target="_blank" rel="noreferrer">agent/src/server.js#L427-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L535" target="_blank" rel="noreferrer">agent/src/server.js#L471-L535</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L548" target="_blank" rel="noreferrer">agent/src/server.js#L427-L548</a></li></ul><h3 id="认证与配对机制" tabindex="-1">认证与配对机制 <a class="header-anchor" href="#认证与配对机制" aria-label="Permalink to &quot;认证与配对机制&quot;">​</a></h3><p>认证模块维护以下状态：</p><ul><li>当前配对码：定时刷新，插件在线时停止刷新，离线超时后恢复刷新。</li><li>最近认证时间：用于判断扩展是否仍在线。</li><li>配对失败计数：连续失败达到阈值后临时锁定，并立即轮换配对码。</li><li>配对记录：存储扩展 ID 与 token，落盘前对 token 加密。</li></ul><pre class="mermaid">stateDiagram-v2
[*] --&gt; Generating : &quot;启动时生成配对码&quot;
Generating --&gt; Rotating : &quot;定时器轮询&quot;
Rotating --&gt; Active : &quot;检测到已配对且最近有认证&quot;
Active --&gt; Rotating : &quot;插件离线超时&quot;
Rotating --&gt; Locked : &quot;连续失败达到阈值&quot;
Locked --&gt; Rotating : &quot;锁定期结束&quot;
Rotating --&gt; Paired : &quot;配对成功&quot;
Paired --&gt; Rotating : &quot;成功后立即轮换配对码&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L102" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L102</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L127" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li></ul><h3 id="路径与命令安全模型" tabindex="-1">路径与命令安全模型 <a class="header-anchor" href="#路径与命令安全模型" aria-label="Permalink to &quot;路径与命令安全模型&quot;">​</a></h3><p>安全模块提供两层保护：</p><ol><li><strong>路径沙箱</strong>：通过 <code>checkPath</code> 校验目标路径是否在 allowedPaths 或 workdir 内，防止符号链接绕过，拦截硬阻止目录。</li><li><strong>命令分级</strong>：通过 <code>checkCommand</code> 对命令进行黑名单（deny）、灰名单（confirm）、允许（allow）分类，支持链式命令拆分、解释器内联载荷、命令替换检测。</li></ol><pre class="mermaid">flowchart TD
Input[&quot;输入路径或命令&quot;] --&gt; Normalize[&quot;路径规整&lt;br/&gt;normalizePathFormat&quot;]
Normalize --&gt; HardBlock{&quot;命中硬阻止目录?&quot;}
HardBlock --&gt; |是| Deny[&quot;deny / forbiddenAgentFile&quot;]
HardBlock --&gt; |否| WorkdirCheck{&quot;是否 workdir?&quot;}
WorkdirCheck --&gt; |是| AllowWorkdir[&quot;允许 workdir&quot;]
WorkdirCheck --&gt; |否| AllowedPaths{&quot;是否在 allowedPaths?&quot;}
AllowedPaths --&gt; |否| NotAllowed[&quot;pathNotInAllowedDir&quot;]
AllowedPaths --&gt; |是| Realpath[&quot;realpath 校验&quot;]
Realpath --&gt; FinalCheck{&quot;realpath 再次白名单?&quot;}
FinalCheck --&gt; |是| Allowed[&quot;allowed&quot;]
FinalCheck --&gt; |否| OutOfRange[&quot;pathOutOfRange&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h3 id="命令执行与-websocket-流式输出" tabindex="-1">命令执行与 WebSocket 流式输出 <a class="header-anchor" href="#命令执行与-websocket-流式输出" aria-label="Permalink to &quot;命令执行与 WebSocket 流式输出&quot;">​</a></h3><p>命令执行器负责：</p><ul><li>选择合适 shell（cmd/powershell/bash/zsh/fish/sh）。</li><li>创建子进程，隔离环境变量，限制输出缓冲区上限。</li><li>支持同步等待模式和异步 WebSocket 流式输出。</li><li>管理超时策略：旧模式到期直接杀，受管模式根据输出情况决定是否延长。</li><li>多客户端广播：同一 execId 可被多个 WebSocket 客户端订阅。</li><li>进程终止：Windows 用 taskkill，Unix 用进程组 SIGTERM/SIGKILL。</li></ul><pre class="mermaid">sequenceDiagram
participant API as &quot;HTTP 接口&quot;
participant EX as &quot;命令执行器&quot;
participant PROC as &quot;子进程&quot;
participant WS as &quot;WebSocket 客户端&quot;
API-&gt;&gt;EX : &quot;executeCommand(command,cwd,timeoutMs)&quot;
EX-&gt;&gt;PROC : &quot;spawn(shell,args,command)&quot;
PROC--&gt;&gt;EX : &quot;stdout/stderr 数据流&quot;
EX-&gt;&gt;WS : &quot;broadcast(stdout/stderr)&quot;
PROC--&gt;&gt;EX : &quot;close(exitCode)&quot;
EX-&gt;&gt;WS : &quot;broadcast(exit)&quot;
WS--&gt;&gt;API : &quot;前端收到实时输出&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li></ul><h3 id="websocket-握手与连接管理" tabindex="-1">WebSocket 握手与连接管理 <a class="header-anchor" href="#websocket-握手与连接管理" aria-label="Permalink to &quot;WebSocket 握手与连接管理&quot;">​</a></h3><p>WebSocket 升级由 <code>server.on(&#39;upgrade&#39;)</code> 处理，仅允许 <code>/ws/exec/{execId}</code> 路径：</p><ol><li>解析 URL，提取 execId。</li><li>同步语言到 executor、security、config 模块。</li><li>认证：优先使用 <code>Authorization: Bearer</code>，回退到 <code>?token=</code> query。</li><li>验证失败直接返回 403。</li><li>验证通过后，将 WebSocket 客户端加入进程的 wsClients 集合。</li><li>启动心跳：每 30 秒 ping，未 pong 则 terminate。</li><li>客户端断开时移除连接，并在无客户端且非受管模式下取消超时。</li></ol><pre class="mermaid">sequenceDiagram
participant Browser as &quot;浏览器 WebSocket&quot;
participant Server as &quot;HTTP 服务器&quot;
participant WSS as &quot;WebSocketServer&quot;
participant EXEC as &quot;命令执行器&quot;
Browser-&gt;&gt;Server : &quot;GET /ws/exec/{execId}?token=...&quot;
Server-&gt;&gt;Server : &quot;验证 Authorization / token&quot;
alt &quot;认证失败&quot;
Server--&gt;&gt;Browser : &quot;403 Forbidden&quot;
else &quot;认证成功&quot;
Server-&gt;&gt;WSS : &quot;handleUpgrade(request,socket,head)&quot;
WSS-&gt;&gt;EXEC : &quot;addWsClient(execId,ws)&quot;
EXEC--&gt;&gt;WSS : &quot;true/false&quot;
WSS-&gt;&gt;WSS : &quot;启动心跳 ping/pong&quot;
WSS--&gt;&gt;Browser : &quot;连接建立&quot;
EXEC--&gt;&gt;WSS : &quot;stdout/stderr/exit 广播&quot;
WSS--&gt;&gt;Browser : &quot;实时消息&quot;
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L429-L479" target="_blank" rel="noreferrer">agent/src/executor.js#L429-L479</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L429-L479" target="_blank" rel="noreferrer">agent/src/executor.js#L429-L479</a></li></ul><h3 id="配置选项与服务发现" tabindex="-1">配置选项与服务发现 <a class="header-anchor" href="#配置选项与服务发现" aria-label="Permalink to &quot;配置选项与服务发现&quot;">​</a></h3><p>配置模块提供默认值与持久化：</p><ul><li>默认端口：18910</li><li>默认 host：127.0.0.1</li><li>workdir：用户工作目录</li><li>allowedPaths：允许访问的目录列表</li><li>pairCodeTTL：配对码过期时间</li><li>commandTimeout：命令默认超时</li><li>fileMaxSize：文件读取大小限制</li><li>memoryEmbedding：长期记忆语义召回配置</li></ul><p>健康检查接口 <code>/api/status</code> 返回版本、运行状态、平台信息、搜索工具可用性、RAG 可用性。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L39" target="_blank" rel="noreferrer">agent/src/config.js#L15-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li></ul><h3 id="反向代理与-ssl-tls-支持" tabindex="-1">反向代理与 SSL/TLS 支持 <a class="header-anchor" href="#反向代理与-ssl-tls-支持" aria-label="Permalink to &quot;反向代理与 SSL/TLS 支持&quot;">​</a></h3><p>当前实现直接使用 Node.js 原生 <code>http</code> 模块，未内置 SSL/TLS 支持。推荐部署方式：</p><ul><li>使用 Nginx、Apache、Caddy 等反向代理提供 HTTPS。</li><li>反向代理转发到 <code>127.0.0.1:18910</code>。</li><li>注意 CORS 策略：仅放行 <code>chrome-extension://</code> 来源，普通网页无法跨域读取响应。</li><li>若暴露到公网，务必通过防火墙或反向代理限制来源 IP。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L242-L266" target="_blank" rel="noreferrer">agent/src/server.js#L242-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L444-L457" target="_blank" rel="noreferrer">agent/src/server.js#L444-L457</a></li></ul><h3 id="服务健康检查、优雅关闭与资源清理" tabindex="-1">服务健康检查、优雅关闭与资源清理 <a class="header-anchor" href="#服务健康检查、优雅关闭与资源清理" aria-label="Permalink to &quot;服务健康检查、优雅关闭与资源清理&quot;">​</a></h3><p>健康检查：</p><ul><li><code>/api/status</code>：无认证，返回基础平台信息。</li><li><code>/api/status/detail</code>：需认证，返回内存、CPU、运行进程、RAG 状态等详细信息。</li><li><code>/api/heartbeat</code>：需认证，刷新 lastAuthTime。</li></ul><p>优雅关闭：</p><ul><li>监听 <code>SIGINT</code>、<code>SIGTERM</code>。</li><li>停止配对码轮换、回收站清理、RAG 安装。</li><li>终止所有运行中的命令进程。</li><li>关闭 MCP 连接。</li><li>强制断开所有 WebSocket 客户端。</li><li>销毁活跃 HTTP socket。</li><li>10 秒超时兜底，防止 <code>server.close()</code> 挂起。</li></ul><p>资源清理：</p><ul><li>PID 文件删除。</li><li>全局 <code>uncaughtException</code>、<code>unhandledRejection</code> 捕获，记录日志但不退出进程。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2308" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2308</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Config[&quot;config.js&quot;]
Server --&gt; Auth[&quot;auth.js&quot;]
Server --&gt; Security[&quot;security.js&quot;]
Server --&gt; Executor[&quot;executor.js&quot;]
Server --&gt; MemoryRoutes[&quot;memory/routes.js&quot;]
Server --&gt; RAG[&quot;rag/* (按需加载)&quot;]
Server --&gt; MCP[&quot;mcp/*&quot;]
Server --&gt; Skill[&quot;skill/*&quot;]
Executor --&gt; ChildProcess[&quot;child_process&quot;]
Server --&gt; WS[&quot;ws&quot;]
Server --&gt; FS[&quot;fs/fs/promises&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L57" target="_blank" rel="noreferrer">agent/src/server.js#L1-L57</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L8" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L8</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L57" target="_blank" rel="noreferrer">agent/src/server.js#L1-L57</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L8" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L8</a></li></ul><h2 id="性能与并发特性" tabindex="-1">性能与并发特性 <a class="header-anchor" href="#性能与并发特性" aria-label="Permalink to &quot;性能与并发特性&quot;">​</a></h2><ul><li><strong>请求体大小限制</strong>：JSON body 最大 200MB，multipart/form-data 同样限制。</li><li><strong>流式上传</strong>：<code>/api/fs/upload-stream</code> 使用 <code>createWriteStream</code>，避免 base64 膨胀。</li><li><strong>流式下载</strong>：<code>/api/fs/download-stream</code> 使用 <code>createReadStream</code>，分块 64KB 写出，避免 OOM。</li><li><strong>ZIP 打包</strong>：使用 <code>archiver</code>，压缩级别 9，临时文件写入 tmpdir，完成后删除。</li><li><strong>命令输出缓冲</strong>：stdout/stderr 最大 5MB，超限标记 truncated 并广播提示。</li><li><strong>超时策略</strong>：受管模式支持最多 5 次延长，总预算封顶 600 秒。</li><li><strong>配置缓存</strong>：内存缓存 + mtime 检测，写入加锁防并发覆盖。</li><li><strong>WebSocket 心跳</strong>：30 秒 ping，检测半开连接。</li><li><strong>进程树终止</strong>：Windows 用 taskkill /T，Unix 用负 PID 进程组信号。</li></ul><p>[本节为通用性能讨论，不直接分析具体代码行]</p><h2 id="api-端点规范" tabindex="-1">API 端点规范 <a class="header-anchor" href="#api-端点规范" aria-label="Permalink to &quot;API 端点规范&quot;">​</a></h2><h3 id="认证与配对" tabindex="-1">认证与配对 <a class="header-anchor" href="#认证与配对" aria-label="Permalink to &quot;认证与配对&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>认证</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/pair</code></td><td>无</td><td>提交 code 和 extensionId，返回 token</td></tr><tr><td>GET</td><td><code>/api/status</code></td><td>无</td><td>返回版本、平台、searchTools、ragAvailable</td></tr><tr><td>GET</td><td><code>/api/heartbeat</code></td><td>Bearer</td><td>刷新 lastAuthTime</td></tr><tr><td>POST</td><td><code>/api/shutdown</code></td><td>本机免认证，远程需 Bearer</td><td>停止 Agent</td></tr><tr><td>POST</td><td><code>/api/agent/restart</code></td><td>Bearer</td><td>重启 Agent</td></tr><tr><td>POST</td><td><code>/api/agent/update</code></td><td>Bearer</td><td>更新并重启 Agent</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L485" target="_blank" rel="noreferrer">agent/src/server.js#L474-L485</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L502-L535" target="_blank" rel="noreferrer">agent/src/server.js#L502-L535</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L603" target="_blank" rel="noreferrer">agent/src/server.js#L555-L603</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L605-L720" target="_blank" rel="noreferrer">agent/src/server.js#L605-L720</a></li></ul><h3 id="文件操作" tabindex="-1">文件操作 <a class="header-anchor" href="#文件操作" aria-label="Permalink to &quot;文件操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>认证</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/files/upload</code></td><td>Bearer</td><td>multipart/form-data 上传</td></tr><tr><td>POST</td><td><code>/api/fs/upload-stream</code></td><td>Bearer</td><td>原始二进制流式上传</td></tr><tr><td>GET/POST</td><td><code>/api/fs/read</code></td><td>Bearer</td><td>读取文件内容</td></tr><tr><td>POST</td><td><code>/api/fs/write</code></td><td>Bearer</td><td>写入文件，支持 utf-8/base64</td></tr><tr><td>POST</td><td><code>/api/fs/list</code></td><td>Bearer</td><td>列出目录</td></tr><tr><td>POST</td><td><code>/api/fs/stat</code></td><td>Bearer</td><td>获取文件详情</td></tr><tr><td>POST</td><td><code>/api/fs/delete</code></td><td>Bearer</td><td>移至回收站</td></tr><tr><td>POST</td><td><code>/api/fs/download</code></td><td>Bearer</td><td>返回 base64 内容</td></tr><tr><td>POST</td><td><code>/api/fs/download-multi</code></td><td>Bearer</td><td>批量打包 ZIP</td></tr><tr><td>POST</td><td><code>/api/fs/download-stream</code></td><td>Bearer</td><td>流式下载</td></tr><tr><td>POST</td><td><code>/api/fs/preview-xlsx</code></td><td>Bearer</td><td>服务端解析 XLSX 前 500 行</td></tr><tr><td>POST</td><td><code>/api/fs/mkdir</code></td><td>Bearer</td><td>创建目录</td></tr><tr><td>POST</td><td><code>/api/fs/rename</code></td><td>Bearer</td><td>重命名</td></tr><tr><td>POST</td><td><code>/api/fs/move</code></td><td>Bearer</td><td>移动文件/目录</td></tr><tr><td>POST</td><td><code>/api/browser/open</code></td><td>Bearer</td><td>本地浏览器打开文件</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L862" target="_blank" rel="noreferrer">agent/src/server.js#L751-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1036-L1601" target="_blank" rel="noreferrer">agent/src/server.js#L1036-L1601</a></li></ul><h3 id="命令执行" tabindex="-1">命令执行 <a class="header-anchor" href="#命令执行" aria-label="Permalink to &quot;命令执行&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>认证</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/exec</code></td><td>Bearer</td><td>执行命令，返回 execId 和 wsUrl</td></tr><tr><td>POST</td><td><code>/api/exec/stop</code></td><td>Bearer</td><td>停止命令</td></tr><tr><td>POST</td><td><code>/api/exec/detach</code></td><td>Bearer</td><td>显式 daemon 化</td></tr></tbody></table><p>WebSocket 地址：<code>ws://{host}:{port}/ws/exec/{execId}?token={token}</code></p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1689" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1689</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li></ul><h3 id="长期记忆" tabindex="-1">长期记忆 <a class="header-anchor" href="#长期记忆" aria-label="Permalink to &quot;长期记忆&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>认证</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/memory/store</code></td><td>Bearer</td><td>存储记忆</td></tr><tr><td>POST</td><td><code>/api/memory/recall</code></td><td>Bearer</td><td>检索记忆</td></tr><tr><td>POST</td><td><code>/api/memory/manage</code></td><td>Bearer</td><td>管理记忆</td></tr><tr><td>POST</td><td><code>/api/memory/injectSelect</code></td><td>Bearer</td><td>注入选择</td></tr><tr><td>POST</td><td><code>/api/memory/reindex</code></td><td>Bearer</td><td>重建向量缓存</td></tr><tr><td>GET</td><td><code>/api/memory/embedding-config</code></td><td>Bearer</td><td>读取 embedding 配置</td></tr><tr><td>POST</td><td><code>/api/memory/embedding-config</code></td><td>Bearer</td><td>保存 embedding 配置</td></tr><tr><td>POST</td><td><code>/api/memory/test-embedding</code></td><td>Bearer</td><td>测试 embedding 连通性</td></tr><tr><td>GET</td><td><code>/api/memory/vector-status</code></td><td>Bearer</td><td>向量缓存状态</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L19-L27" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L19-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L77-L137" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L77-L137</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/memory/routes.js#L149-L199" target="_blank" rel="noreferrer">agent/src/memory/routes.js#L149-L199</a></li></ul><h3 id="其他功能" tabindex="-1">其他功能 <a class="header-anchor" href="#其他功能" aria-label="Permalink to &quot;其他功能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>认证</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/config/workdir</code></td><td>Bearer</td><td>切换工作目录</td></tr><tr><td>POST</td><td><code>/api/config/allowed-paths/remove</code></td><td>Bearer</td><td>移除允许目录</td></tr><tr><td>GET</td><td><code>/api/trash/list</code></td><td>Bearer</td><td>回收站列表</td></tr><tr><td>POST</td><td><code>/api/trash/restore</code></td><td>Bearer</td><td>恢复回收站文件</td></tr><tr><td>GET</td><td><code>/api/logs/query</code></td><td>Bearer</td><td>查询审计日志</td></tr><tr><td>GET/POST</td><td><code>/api/skill/*</code></td><td>Bearer</td><td>技能管理</td></tr><tr><td>GET/POST/DELETE</td><td><code>/api/mcp/*</code></td><td>Bearer</td><td>MCP 工具管理</td></tr><tr><td>GET/POST</td><td><code>/api/rag/*</code></td><td>Bearer</td><td>RAG 知识库（可选依赖）</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L872-L983" target="_blank" rel="noreferrer">agent/src/server.js#L872-L983</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1693-L1766" target="_blank" rel="noreferrer">agent/src/server.js#L1693-L1766</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1768-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1768-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2006-L2067" target="_blank" rel="noreferrer">agent/src/server.js#L2006-L2067</a></li></ul><h2 id="错误码与响应约定" tabindex="-1">错误码与响应约定 <a class="header-anchor" href="#错误码与响应约定" aria-label="Permalink to &quot;错误码与响应约定&quot;">​</a></h2><p>所有接口统一返回 JSON 结构：</p><ul><li>成功：<code>{ success: true, ... }</code></li><li>失败：<code>{ success: false, error: &quot;错误文案&quot; }</code></li></ul><p>常见 HTTP 状态码：</p><ul><li>200：成功</li><li>400：参数错误、JSON 解析失败、文件大小超限</li><li>401：缺少 Authorization 或 Bearer Token</li><li>403：Token 无效、路径不在白名单、命令被拒绝</li><li>404：未知 API 路径</li><li>409：操作进行中、目标已存在</li><li>429：操作过于频繁</li><li>500：内部错误、RAG 路由加载失败</li><li>503：RAG 依赖不可用</li></ul><p>错误文案来自 i18n，键名如 <code>error.bodyTooLarge</code>、<code>error.invalidToken</code>、<code>security.pathNotInAllowedDir</code> 等。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L253-L266" target="_blank" rel="noreferrer">agent/src/server.js#L253-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L271-L303" target="_blank" rel="noreferrer">agent/src/server.js#L271-L303</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2074-L2075" target="_blank" rel="noreferrer">agent/src/server.js#L2074-L2075</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>排查建议</th></tr></thead><tbody><tr><td>端口占用</td><td>已有 Agent 进程</td><td>检查 <code>.ai-helper-agent/agent.pid</code>，或使用 <code>/api/shutdown</code> 停止</td></tr><tr><td>认证失败</td><td>Token 无效或过期</td><td>重新配对，检查 <code>pairings.json</code></td></tr><tr><td>路径被拒绝</td><td>不在 allowedPaths 或 workdir</td><td>检查 <code>config.json</code> 的 allowedPaths 和 workdir</td></tr><tr><td>命令被拒绝</td><td>命中黑名单或灰名单</td><td>查看 security.js 的 BLACKLIST_PATTERNS 和 GRAYLIST_PATTERNS</td></tr><tr><td>WebSocket 断连</td><td>浏览器空闲、网络闪断、心跳未 pong</td><td>检查前端心跳逻辑，确认 <code>/ws/exec/{execId}</code> 连接存活</td></tr><tr><td>命令无输出</td><td>子进程静默失败、输出缓冲截断</td><td>查看 stderr 和 truncated 提示</td></tr><tr><td>RAG 不可用</td><td>依赖未安装或 Node 版本不兼容</td><td>调用 <code>/api/rag/install</code> 和 <code>/api/rag/detect</code></td></tr><tr><td>优雅关闭卡住</td><td>仍有活跃 socket 或子进程</td><td>检查 activeSockets 和 runningProcesses</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2155-L2163" target="_blank" rel="noreferrer">agent/src/server.js#L2155-L2163</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2308" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2308</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L496-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L496-L549</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Agent 的 HTTP/WebSocket 服务器以 Node.js 原生模块为基础，实现了完整的安全控制、文件操作、命令执行、长期记忆、RAG、MCP 和 Skill 管理能力。其设计强调：</p><ul><li>安全优先：路径白名单、硬阻止目录、命令黑白名单、配对码轮换、Token 认证。</li><li>可扩展：模块化路由、按需加载 RAG、MCP、Skill。</li><li>健壮性：优雅关闭、全局异常捕获、进程树终止、心跳检测。</li><li>可观测：审计日志、平台信息、资源使用统计。</li></ul><p>对于生产部署，建议通过反向代理提供 HTTPS，严格限制来源 IP，并配合防火墙和监控告警。对于开发者，应遵循 i18n 文案、统一响应格式和安全校验流程，避免绕过 <code>checkPath</code> 和 <code>checkCommand</code>。</p><p>[本节为总结性内容，不直接分析具体代码行]</p>`,138)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
